<?php
declare(strict_types=1);
namespace ReadyFinance;
final class ReportingService {
 public function __construct(private Core $c){}
 public function snapshot(int $h,array $user):array{
  $c=$this->c;$today=$c->today($h);$month=substr($today,0,7);$house=$c->one('SELECT uuid,name,currency,timezone FROM households WHERE id=?',[$h]);$accounts=$c->all('SELECT a.uuid,a.name,a.type,a.currency,a.active,a.ledger_id,COALESCE(SUM(l.debit-l.credit),0) balance FROM accounts a LEFT JOIN journal_lines l ON l.ledger_id=a.ledger_id AND l.household_id=a.household_id WHERE a.household_id=? GROUP BY a.id ORDER BY a.id',[$h]);
  $planning=(new PlanManagementService($c))->ready();$planColumns=fn($alias)=>$planning?','.$alias.'.archived,'.$alias.'.row_version':'';$editing=(new AccountManagementService($c))->ready();$cats=$c->all('SELECT ca.uuid,ca.name,ca.type,l.uuid ledger_uuid,l.system_key'.($editing?',l.active':'').' FROM categories ca JOIN ledger_accounts l ON l.id=ca.ledger_id AND l.household_id=ca.household_id WHERE ca.household_id=? ORDER BY ca.type,ca.name',[$h]);
  $tx=$c->all("SELECT t.uuid,t.type,t.effective_date,t.description,t.amount,t.status,t.created_at,t.row_version,".($editing?'t.replaces_id,t.edit_reason,':'')."EXISTS(SELECT 1 FROM journal_entries je JOIN journal_lines jl ON jl.journal_id=je.id AND jl.household_id=je.household_id JOIN ledger_accounts l ON l.id=jl.ledger_id AND l.household_id=jl.household_id WHERE je.transaction_id=t.id AND je.household_id=t.household_id AND l.system_key IN ('uncategorized_expense','uncategorized_income')) needs_review FROM transactions t WHERE t.household_id=? ORDER BY t.effective_date DESC,t.id DESC LIMIT 500",[$h]);
  $stats=$c->one("SELECT COALESCE(SUM(IF(a.class='expense',l.debit-l.credit,0)),0) spending,COALESCE(SUM(IF(a.class='income',l.credit-l.debit,0)),0) income FROM journal_lines l JOIN ledger_accounts a ON a.id=l.ledger_id JOIN journal_entries j ON j.id=l.journal_id WHERE l.household_id=? AND j.effective_date>=? AND j.effective_date<?",[$h,$month.'-01',(new \DateTimeImmutable($month.'-01'))->modify('+1 month')->format('Y-m-d')]);
  $bills=$c->all('SELECT b.uuid,b.name,b.amount,b.due_date,ca.uuid category_uuid'.$planColumns('b').',COALESCE(SUM(ba.amount),0) paid FROM bills b JOIN categories ca ON ca.id=b.category_id LEFT JOIN bill_allocations ba ON ba.bill_id=b.id AND ba.household_id=b.household_id WHERE b.household_id=? GROUP BY b.id ORDER BY b.due_date',[$h]);
  foreach($bills as &$b){$b['remaining']=bcsub($b['amount'],$b['paid'],6);$b['state']=bccomp($b['remaining'],'0',6)<=0?'paid':(bccomp($b['paid'],'0',6)>0?'partial':($b['due_date']<$today?'overdue':'upcoming'));}unset($b);
  $budgets=[]; // Retired plan data stays in the database and backups.
  $funds=[];
  $debts=[];
  $spending=$c->all("SELECT ca.name,ca.uuid,COALESCE(SUM(l.debit-l.credit),0) amount FROM categories ca JOIN journal_lines l ON l.category_id=ca.id JOIN journal_entries j ON j.id=l.journal_id WHERE ca.household_id=? AND ca.type='expense' AND j.effective_date>=? AND j.effective_date<? GROUP BY ca.id ORDER BY amount DESC",[$h,$month.'-01',(new \DateTimeImmutable($month.'-01'))->modify('+1 month')->format('Y-m-d')]);
  $cash='0';$reserved='0';foreach($accounts as $a)if($a['type']!=='credit_card')$cash=bcadd($cash,$a['balance'],6);foreach($funds as $f)$reserved=bcadd($reserved,$f['reserved'],6);
  $trend=[];
  $net=(string)$c->query("SELECT COALESCE(SUM(l.debit-l.credit),0) FROM journal_lines l JOIN ledger_accounts a ON a.id=l.ledger_id WHERE l.household_id=? AND a.class IN ('asset','liability')",[$h])->fetchColumn();
  $parties=(new PartyService($c))->listing($h);$assets=$editing?$c->all("SELECT l.uuid,l.name,l.class,l.account_kind,l.active,COALESCE(SUM(j.debit-j.credit),0) balance FROM ledger_accounts l LEFT JOIN journal_lines j ON j.ledger_id=l.id AND j.household_id=l.household_id WHERE l.household_id=? AND l.class='asset' AND l.is_group=0 AND l.account_kind NOT IN ('receivable','bank','cash','wallet','savings') AND NOT EXISTS(SELECT 1 FROM accounts a WHERE a.household_id=l.household_id AND a.ledger_id=l.id) GROUP BY l.id ORDER BY l.name",[$h]):[];
  return ['party_invoices'=>(new PartyService($c))->ready()?$c->all("SELECT t.uuid,t.type,t.effective_date,t.description,t.amount,t.status,t.row_version,t.replaces_id,e.action FROM party_entries e JOIN transactions t ON t.id=e.transaction_id AND t.household_id=e.household_id WHERE e.household_id=? AND e.action IN ('invoice','supplier_bill') AND t.status='posted' ORDER BY t.effective_date DESC,t.id DESC LIMIT 100",[$h]):[],'parties_listing'=>$parties,'assets'=>$assets,'cashflow'=>$this->cashflow($h,$month),'planning_ready'=>$planning,'editing_ready'=>$editing,'household'=>$house,'user'=>['name'=>$user['name'],'email'=>$user['email'],'role'=>$user['role']],'today'=>$today,'accounts'=>$accounts,'categories'=>$cats,'transactions'=>(new PartyService($c))->labelRows($h,$tx),'bills'=>$bills,'budgets'=>$budgets,'funds'=>$funds,'debts'=>$debts,'members'=>$c->all('SELECT uuid,name,relationship FROM members WHERE household_id=?',[$h]),'recurring'=>[],'documents'=>$c->all('SELECT uuid,filename,mime,bytes,created_at FROM documents WHERE household_id=? ORDER BY id DESC LIMIT 100',[$h]),'audit'=>$c->all('SELECT action,entity_uuid,created_at FROM audit_events WHERE household_id=? ORDER BY id DESC LIMIT 50',[$h]),'periods'=>$c->all('SELECT month,locked,reason FROM periods WHERE household_id=? ORDER BY month DESC LIMIT 24',[$h]),'spending'=>$spending,'trend'=>array_reverse($trend),'stats'=>$stats+['cash'=>$cash,'reserved'=>$reserved,'available'=>bcsub($cash,$reserved,6),'net_worth'=>$net]];
 }
 public function cashflow(int $h,string $month):array {
  return $this->c->one("SELECT COALESCE(SUM(IF(t.type='reversal',-l.credit,l.debit)),0) incoming,COALESCE(SUM(IF(t.type='reversal',-l.debit,l.credit)),0) outgoing FROM journal_lines l JOIN journal_entries j ON j.id=l.journal_id AND j.household_id=l.household_id JOIN transactions t ON t.id=j.transaction_id AND t.household_id=j.household_id LEFT JOIN transactions original ON original.id=t.reversal_of AND original.household_id=t.household_id JOIN accounts a ON a.ledger_id=l.ledger_id AND a.household_id=l.household_id WHERE l.household_id=? AND a.type<>'credit_card' AND COALESCE(original.type,t.type)<>'opening' AND j.effective_date>=? AND j.effective_date<? AND (SELECT COUNT(DISTINCT a2.id) FROM journal_lines l2 JOIN accounts a2 ON a2.ledger_id=l2.ledger_id AND a2.household_id=l2.household_id WHERE l2.journal_id=j.id AND l2.household_id=j.household_id AND a2.type<>'credit_card')<2",[$h,$month.'-01',(new \DateTimeImmutable($month.'-01'))->modify('+1 month')->format('Y-m-d')]);
 }

}
